import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const root = process.cwd();

function pathOf(path: string) {
  return join(root, path);
}

function read(path: string) {
  return readFileSync(pathOf(path), "utf8");
}

function write(path: string, content: string) {
  mkdirSync(dirname(pathOf(path)), { recursive: true });
  writeFileSync(pathOf(path), content);
}

function replaceOnce(path: string, search: string, replacement: string) {
  const content = read(path);
  const first = content.indexOf(search);
  if (first < 0) throw new Error(`Anchor not found in ${path}: ${search.slice(0, 120)}`);
  if (content.indexOf(search, first + search.length) >= 0) {
    throw new Error(`Anchor is not unique in ${path}: ${search.slice(0, 120)}`);
  }
  write(path, content.slice(0, first) + replacement + content.slice(first + search.length));
}

function assertAbsent(path: string, needle: string) {
  if (read(path).includes(needle)) throw new Error(`${path} already contains ${needle}`);
}

