write(
  "apps/backend/src/plugins/programme/academic-calendar-router.test.ts",
  `import { describe, expect, test } from "bun:test";\nimport type { AuthUser } from "../../core/auth/token.ts";\nimport { canReadAcademicCalendar, canWriteAcademicCalendar } from "./academic-calendar-router.ts";\nfunction user(programmeRoles: AuthUser["programmeRoles"]): AuthUser { return { id: crypto.randomUUID(), email: "calendar-access@example.test", roles: [...new Set(programmeRoles.map((assignment) => assignment.role))], programmeRoles }; }\ndescribe("academic calendar programme authorization", () => {\n  test("allows programme-scoped staff reads but limits writes to coordinator/admin", () => {\n    expect(canReadAcademicCalendar(user([{ role: "admin", programmeId: null }]), "dse")).toBe(true);\n    expect(canReadAcademicCalendar(user([{ role: "program_coordinator", programmeId: "dse" }]), "dse")).toBe(true);\n    expect(canReadAcademicCalendar(user([{ role: "program_secretary", programmeId: "dse" }]), "dse")).toBe(true);\n    expect(canWriteAcademicCalendar(user([{ role: "program_coordinator", programmeId: "dse" }]), "dse")).toBe(true);\n    expect(canWriteAcademicCalendar(user([{ role: "program_secretary", programmeId: "dse" }]), "dse")).toBe(false);\n  });\n  test("fails closed across programmes and for student/lecturer roles", () => {\n    expect(canReadAcademicCalendar(user([{ role: "program_coordinator", programmeId: "other" }]), "dse")).toBe(false);\n    expect(canWriteAcademicCalendar(user([{ role: "program_coordinator", programmeId: "other" }]), "dse")).toBe(false);\n    expect(canReadAcademicCalendar(user([{ role: "student", programmeId: "dse" }]), "dse")).toBe(false);\n    expect(canReadAcademicCalendar(user([{ role: "lecturer", programmeId: "dse" }]), "dse")).toBe(false);\n  });\n});\n`,
);
write(
  "apps/backend/src/plugins/programme/academic-calendar-domain.test.ts",
  `import { describe, expect, test } from "bun:test";\nimport { AcademicCalendarPeriodInputSchema, CreateAcademicCalendarSchema } from "@dse-pms/shared-types";\nimport { buildAcademicCalendarTimeline } from "./academic-calendar-service.ts";\ndescribe("academic calendar domain", () => {\n  test("rejects reversed teaching periods and half-defined exam ranges", () => {\n    expect(AcademicCalendarPeriodInputSchema.safeParse({ semester: "First", teachingStart: "2026-09-20", teachingEnd: "2026-09-01" }).success).toBe(false);\n    expect(AcademicCalendarPeriodInputSchema.safeParse({ semester: "First", teachingStart: "2026-09-01", teachingEnd: "2027-01-15", examStart: "2027-01-20" }).success).toBe(false);\n  });\n  test("supports one calendar shared by Years 3 and 4 without duplicate semesters", () => {\n    const result = CreateAcademicCalendarSchema.safeParse({ academicYearId: crypto.randomUUID(), studyYears: [3, 4], periods: [{ semester: "First", teachingStart: "2026-09-16", teachingEnd: "2027-01-16" }], events: [], sourceTitle: "Official notice", sourceNote: "Faculty notice" });\n    expect(result.success).toBe(true);\n    expect(CreateAcademicCalendarSchema.safeParse({ academicYearId: crypto.randomUUID(), studyYears: [3, 3], periods: [{ semester: "First", teachingStart: "2026-09-16", teachingEnd: "2027-01-16" }], events: [] }).success).toBe(false);\n  });\n  test("next-event timeline excludes already ended events deterministically", () => {\n    const events = buildAcademicCalendarTimeline([{ id: "p1", calendarId: "c1", semester: "First", teachingStart: "2026-09-01", teachingEnd: "2027-01-10", examStart: "2027-01-15", examEnd: "2027-01-20", breakStart: null, breakEnd: null }], [{ id: "e1", calendarId: "c1", title: "Orientation", type: "Orientation", semester: "First", startDate: "2026-08-20", endDate: "2026-08-20", note: "", sortOrder: 0 }], "2026-08-25");\n    expect(events[0]?.title).toBe("Semester 1 teaching");\n    expect(events.some((event) => event.title === "Orientation")).toBe(false);\n  });\n});\n`,
);

write(
  "docs/academic-calendar-ownership.md",
  `# Academic Calendar ownership and revision rules\n\nEpic #638 establishes **Academic Calendar** as the canonical source of programme academic-period dates.\n\n- **Curriculum** owns which courses belong to a study year and semester.\n- **Academic Calendar** owns official academic-year, teaching, examination, break, and programme academic-event dates.\n- **Course Offering** references a published calendar period; it owns section, lecturer, timetable meetings, enrolments, assessment deadlines, and delivery state. New offerings do not redefine canonical semester dates.\n- **ProgrammeImportantDate** continues to own admissions/public-marketing dates that are not academic-calendar records. Public channels may project published calendar dates, but must not copy them into a competing source of truth.\n- **Student Portal / handbook / public channels** consume published projections only. Draft calendars are never a downstream data source.\n\n## Published corrections\n\nPublished calendar content is immutable. A correction creates a new Draft revision in the same calendar series. Publishing that revision supersedes the previous revision. Planned/Active Offerings are rebound to the equivalent new semester period so current delivery follows the corrected canonical dates; Completed Offerings retain their old period reference so historical academic evidence remains reconstructable.\n\n## Missing calendars\n\nA study year may legitimately have no published calendar. Consumers return an explicit unavailable state and never borrow dates from another study year or fabricate defaults.\n`,
);

